import React, { Component } from "react";
import "./Help.css";

class ChatComponent extends Component {
  constructor(props) {
    super(props);
    this.state = {
      messages: [],
      newMessage: "",
    };
  }

  handleChange = (event) => {
    this.setState({ newMessage: event.target.value });
  };

  handleSubmit = () => {
    const currentTime = new Date().toLocaleTimeString();
    const newMessageObject = {
      text: this.state.newMessage,
      time: currentTime,
    };
    this.setState((prevState) => ({
      messages: [...prevState.messages, newMessageObject],
      newMessage: "",
    }));
  };

  render() {
    return (
      <div className="chat-container">
        <div className="chat-messages">
          {this.state.messages.map((message, index) => (
            <div key={index} className="chat-message">
              <span className="chat-message-text">{message.text}</span>
              <span className="chat-message-time">{message.time}</span>
            </div>
          ))}
        </div>
        <input
          type="text"
          value={this.state.newMessage}
          onChange={this.handleChange}
          className="chat-input"
        />
        <button onClick={this.handleSubmit} className="chat-button">Send</button>
        <button onClick={this.props.onEndChat} className="chat-button">End Chat</button>
      </div>
    );
  }
}

export default ChatComponent;
